import json
n=28
g=[[0]*n for _ in range(n)]
starts=[0,5,10,15,20,25]
ends=[4,9,14,19,24,28]
for k in (4,9,14,19,24):
    g[k]=[8]*n
    for r in range(n): g[r][k]=8
# color each cell; accumulate line colors, with crossings represented by 6
cells={}
def mark(r,c,color): cells[(r,c)]=cells.get((r,c),0)+color
for c in range(5): mark(1,c,2)
for r in range(1,4): mark(r,0,2)
for r in range(5): mark(r,2,3)
for (r,c),v in cells.items():
    color=6 if v==5 else v
    for y in range(starts[r],ends[r]):
        for x in range(starts[c],ends[c]): g[y][x]=color
print(json.dumps(g,separators=(',',':')))

